import {colonyBorderPath} from './colony-borders.mjs';
import {stageOf} from './fragment-buds.mjs';
export function rimAnchor(hub,angle,theme='paperlight',outline=null){const tilt=(hub.plot?.tilt||0)*Math.PI/180,a=angle-tilt,dx=Math.cos(a),dy=Math.sin(a),d=outline||colonyBorderPath(theme,(hub.plot?.rx||hub.size)*1.035,(hub.plot?.ry||hub.size)*1.035,hub.key,0,{wobble:hub.growth?.complexity||1,envelope:hub.plot?.envelope}),points=[...d.matchAll(/C([^CZ]+)/g)].map(m=>{const n=m[1].match(/-?\d+(?:\.\d+)?/g).map(Number);return n.slice(-2);});let reach=Infinity;
 for(let i=0;i<points.length;i++){const p=points[i],q=points[(i+1)%points.length],ex=q[0]-p[0],ey=q[1]-p[1],det=dx*ey-dy*ex;if(Math.abs(det)<1e-8)continue;const r=(p[0]*ey-p[1]*ex)/det,u=(p[0]*dy-p[1]*dx)/det;if(r>=0&&u>=0&&u<=1)reach=Math.min(reach,r);}
 if(!Number.isFinite(reach))reach=hub.size/2;return [hub.x+Math.cos(angle)*reach,hub.y+Math.sin(angle)*reach];
}
// Small fragments are grafted onto their own domain rim; they are not extra posts.
export function rimFragmentSpots(layout,plan,{theme='paperlight'}={}){const all=[...layout.points.values()],hubs=all.filter(p=>!p.owner&&!p.discovery),out=[];for(const {point,frags}of plan){const hub=point.owner?layout.points.get(point.owner):point,base=Math.atan2(hub.y-(layout.core?.y||0),hub.x-(layout.core?.x||0));for(const [i,frag]of frags.entries()){let found;for(const turn of [0,.25,-.25,.5,-.5,.8,-.8,1.1,-1.1,1.5,-1.5,2,-2,Math.PI]){const angle=base+turn+(i?.16:0),anchor=rimAnchor(hub,angle,theme),x=anchor[0]+Math.cos(angle)*24,y=anchor[1]+Math.sin(angle)*24;if(all.some(p=>p!==hub&&Math.hypot(x-p.x,y-p.y)<p.size/2+36)||out.some(p=>Math.hypot(x-p.x,y-p.y)<85)||hubs.some(h=>h!==hub&&Math.hypot((x-h.x)/h.plot.rx,(y-h.y)/h.plot.ry)<1.2))continue;found={x,y,anchor,angle,frag,domainKey:hub.key,stage:stageOf(frag),flip:i%2?1:-1};break;}if(found)out.push(found);}}return out;}
