function draw({transition=false,reset=false,reframe=false,sourcePage=0}={}){if(!state.model)return;syncBrand();document.body.dataset.regionExpression=regionExpression().id;collectionUI.updateBadge();document.body.dataset.scheme=state.theme;if(collectionUI.screen==='atlas'){collectionUI.renderAtlas();return;}for(const mode of Object.keys(names)){byId(mode+'-host').hidden=mode!==state.mode;byId('tab-'+mode).setAttribute('aria-selected',String(mode===state.mode));byId('tab-'+mode).tabIndex=mode===state.mode?0:-1;}byId('chart-title').textContent=names[state.mode];byId('plot-panel').setAttribute('aria-labelledby','tab-'+state.mode);byId('field-options').hidden=state.mode!=='field';document.body.dataset.scheme=state.theme;byId('choose-elements').href='elements.html'+(prototypeStyles[state.theme]?'?style='+state.theme:'');byId('chart').dataset.mode=state.mode;stageHeight();if(living){const opportunities=collectionOpportunities(state.model);byId('garden-lenses').hidden=state.mode!=='field';for(const button of document.querySelectorAll('[data-lens]')){button.setAttribute('aria-pressed',String(button.dataset.lens===state.lens));const badge=button.querySelector('span');if(badge)badge.textContent=button.dataset.lens==='bridges'?state.model.relations.length:button.dataset.lens==='fresh'?state.freshCount:opportunities.pending.length;}}if(state.mode==='field')navigation(null);engine(state.mode).draw(state.model,{path:state.path,page:state.page,expanded:state.gardenExpanded,selected:state.selected,theme:state.theme,density:'auto',sourcePage,showRelations:state.showRelations,collection:true,resolveArt:collectionUI.resolveArt,landmarks:collectionUI.landmarks(),discoveries:collectionUI.mapDiscoveries(),fresh:state.fresh,pinned:collectionUI.progress.pinned,living,lens:state.lens,focus:living?opportunityFocus(state.model,state.lens):null,transition,reset,reframe});}
async function refresh(){const job=++state.request;state.controller?.abort();state.controller=new AbortController();byId('refresh').disabled=true;try{const payload=await readKnowledge({cache:'no-store',signal:state.controller.signal});if(job!==state.request)return;state.model=buildModel(payload);state.model.records.set(ROOT,brandRecord(state.model));state.gardenExpanded=new Set([ROOT,...roots(state.model).map(r=>r.key)]);{const f=freshness(state.model);state.fresh=f.keys;state.freshCount=f.sources.length;const since=sinceLastVisit(state.model),t=byId('collection-toast');if(t&&(since.first||since.fresh.length)){t.textContent=since.first?`欢迎来到花园：${state.model.sources.length} 篇收藏正在生长`:`自上次来访，花园新长出 ${since.fresh.length} 株`;t.hidden=false;const shown=t.textContent;setTimeout(()=>{if(t.textContent===shown)t.hidden=true;},3600);}}if(!state.model.records.has(state.selected))state.selected=ROOT;byId('totals').textContent=state.model.sources.length+' 篇收藏'+(payload.cachedOnly?' · 本地索引':'');byId('node-registry').replaceChildren();for(const record of state.model.records.values())if(['brand','domain','topic','source','pending','unassigned'].includes(record.kind)){const item=el('span');item.dataset.key=record.key;item.dataset.kind=record.kind;byId('node-registry').append(item);}byId('error').hidden=true;state.history=[];draw();reader();if(search.value.trim())search.oninput();}catch(error){if(error.name==='AbortError'||job!==state.request)return;console.error('Kumo garden refresh failed',error);byId('error').textContent=error.message||'暂时无法读取收藏，请在收藏页设置中检查。';const setup=el('a','打开收藏设置');setup.href='../library.html';byId('error').append(document.createTextNode(' '),setup);byId('error').hidden=false;}finally{if(job===state.request)byId('refresh').disabled=false;}}
