const search=byId('search'),results=byId('search-results');function closeSearch(){results.hidden=true;}
search.oninput=()=>{if(collectionUI.screen==='atlas'){collectionUI.setQuery(search.value);return;}const query=search.value.trim().toLowerCase();results.replaceChildren();if(!query||!state.model){closeSearch();return;}const matches=[...state.model.records.values()].filter(r=>['source','domain','topic'].includes(r.kind)&&[r.name,r.summary,...r.keywords||[]].join(' ').toLowerCase().includes(query));for(const record of matches.slice(0,12)){const button=el('button',record.name);button.onclick=()=>{activate(record.key);search.value='';closeSearch();};results.append(button);}if(!matches.length)results.append(el('p','未找到相关收藏'));results.hidden=false;};search.onkeydown=event=>{if(event.key==='Escape')closeSearch();if(event.key==='Enter')results.querySelector('button')?.click();if(event.key==='ArrowDown'){event.preventDefault();results.querySelector('button')?.focus();}};results.onkeydown=event=>{const buttons=[...results.querySelectorAll('button')],i=buttons.indexOf(document.activeElement);if(['ArrowDown','ArrowUp'].includes(event.key)){event.preventDefault();buttons[(i+(event.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus();}if(event.key==='Escape'){closeSearch();search.focus();}};document.addEventListener('pointerdown',event=>{if(!event.target.closest('.search-wrap'))closeSearch();});window.addEventListener('storage',event=>{if(['kumo:garden:chosen-elements:v1','kumo:garden:forest-texture:v1'].includes(event.key)&&(state.theme==='garden'||prototypeStyles[state.theme]))draw();});window.addEventListener('pagehide',()=>{state.controller?.abort();for(const e of engines.values())e.dispose();});new ResizeObserver(()=>{if(state.model&&state.mode==='field')stageHeight();}).observe(byId('chart'));for(const b of document.querySelectorAll('[data-lens]'))b.onclick=()=>setLens(b.dataset.lens);await refresh();

